        "min_age": 18,
        "max_age": 90,
        "required_consent_version": "v2",
        "consent_valid_from": "2024-01-01",
        "labs": {"A": [1, 3]},
        "exclusions": ["DO_NOT_ENROLL"],
    }


def make_subject():
    return {
        "birth_date": "1990-06-15",
        "consents": [{"version": "v2", "signed_on": "2024-01-01"}],
        "labs": {"A": 2},
        "flags": [],
    }


def book_kwargs(capacity, **changes):
    kwargs = {
        "on": date(2024, 6, 1),
        "first_day": date(2024, 6, 1),
        "offsets_months": [0, 1],
        "hour": 9,
        "minute": 0,
        "timezone": "America/New_York",
        "capacity": capacity,
    }
    kwargs.update(changes)
    return kwargs


def test_book_subject_visits_decrements_only_listed_capacity_dates():
    capacity = {date(2024, 6, 1): 1}
    subject = make_subject()
    protocol = make_protocol()
    subject_snapshot = deepcopy(subject)
    protocol_snapshot = deepcopy(protocol)

    visits = book_subject_visits(subject, protocol, **book_kwargs(capacity))

    assert visits == [
        {
            "offset_months": 0,
            "local": "2024-06-01T09:00:00-04:00",
            "utc": "2024-06-01T13:00:00Z",
        },
        {
            "offset_months": 1,
            "local": "2024-07-01T09:00:00-04:00",
            "utc": "2024-07-01T13:00:00Z",
        },
    ]
    # Only the listed 2024-06-01 is decremented; 2024-07-01 is never inserted.
    assert capacity == {date(2024, 6, 1): 0}
    assert subject == subject_snapshot
    assert protocol == protocol_snapshot


def test_sequential_slot_contention_pushes_later_subjects_forward():
    capacity = {date(2024, 6, 1): 1}

    first = book_subject_visits(make_subject(), make_protocol(), **book_kwargs(capacity))
    second = book_subject_visits(
        make_subject(), make_protocol(), **book_kwargs(capacity)
    )

    assert [visit["local"][:10] for visit in first] == ["2024-06-01", "2024-07-01"]
    # The second subject cannot reuse the exhausted 06-01 slot, so its first
    # visit moves forward; the second visit keeps its own nominal day.
    assert [visit["local"][:10] for visit in second] == ["2024-06-02", "2024-07-01"]
    assert capacity == {date(2024, 6, 1): 0}


def test_later_visit_rolls_back_the_whole_booking():
    capacity = {date(2024, 6, 1): 1}
    # The second visit's candidate window is fully closed, so planning fails
    # after the first visit would have consumed the 06-01 slot.
    closed = {date(2024, 7, day) for day in range(1, 32)} | {
        date(2024, 7, day) + timedelta(days=days) for day in (1,) for days in range(367)
    }

    with pytest.raises(ValueError, match="UNSCHEDULABLE"):
        book_subject_visits(
            make_subject(),
            make_protocol(),
            **book_kwargs(
                capacity,
                closed_days=closed,
                offsets_months=[0, 1],
            ),
        )

    assert capacity == {date(2024, 6, 1): 1}


def test_ineligible_subject_raises_ordered_reasons_and_keeps_capacity():
    subject = make_subject()
    subject.update(
        birth_date="2005-06-15",
        consents=[{"version": "v1", "signed_on": "2023-12-31"}],
        flags=["DO_NOT_ENROLL"],
        labs={"A": 99},
    )
    capacity = {date(2024, 6, 1): 3}
    subject_snapshot = deepcopy(subject)

    with pytest.raises(ValueError, match="INELIGIBLE:CONSENT_MISSING"):
        book_subject_visits(subject, make_protocol(), **book_kwargs(capacity))

    assert capacity == {date(2024, 6, 1): 3}
    assert subject == subject_snapshot

    with pytest.raises(
        ValueError,
        match="INELIGIBLE:CONSENT_MISSING,CONSENT_VERSION,AGE_BELOW_MIN,"
        "EXCLUSION_DO_NOT_ENROLL,LAB_A_HIGH",
    ):
        book_subject_visits(subject, make_protocol(), **book_kwargs(capacity))


def test_earlier_successful_booking_stays_committed_after_a_later_failure():
    capacity = {date(2024, 6, 1): 1}

    committed = book_subject_visits(
        make_subject(), make_protocol(), **book_kwargs(capacity)
    )
    assert capacity == {date(2024, 6, 1): 0}

    # A later failing call must not undo the committed reservation, nor can it
    # consume the already-exhausted slot.
    with pytest.raises(ValueError, match="UNSCHEDULABLE"):
        book_subject_visits(
            make_subject(),
            make_protocol(),
            **book_kwargs(
                capacity,
                closed_days={
                    date(2024, 6, day) + timedelta(days=days)
                    for day in range(1, 31)
                    for days in (0,)
                }
                | {
                    date(2024, 7, day) + timedelta(days=days)
                    for day in range(1, 32)
                    for days in (0,)
                },
            ),
        )

    assert capacity == {date(2024, 6, 1): 0}
    assert [visit["local"][:10] for visit in committed] == [
        "2024-06-01",
        "2024-07-01",
    ]


def test_booking_preserves_dst_and_month_end_behaviour():
    capacity = {date(2024, 3, 10): 1}

    visits = book_subject_visits(
        make_subject(),
        make_protocol(),
        **book_kwargs(
            capacity,
            first_day=date(2024, 1, 31),
            offsets_months=[1, 2],
            hour=2,
            minute=30,
            timezone="America/New_York",
        ),
    )

    assert visits == [
        {
            "offset_months": 1,
            "local": "2024-02-29T02:30:00-05:00",
            "utc": "2024-02-29T07:30:00Z",
        },
        {
            "offset_months": 2,
            "local": "2024-03-31T02:30:00-04:00",
            "utc": "2024-03-31T06:30:00Z",
        },
    ]
    # 2024-03-31 is unlisted, so it is never inserted or decremented.
    assert capacity == {date(2024, 3, 10): 1}


def test_book_subject_visits_delegates_validation_and_never_mutates_closed_days():
    capacity = {date(2024, 6, 1): 1}
    closed = [date(2024, 6, 1)]
    closed_snapshot = deepcopy(closed)

    with pytest.raises(ValueError, match="INVALID_TIMEZONE"):
        book_subject_visits(
            make_subject(),
            make_protocol(),
            **book_kwargs(
